class HomeTab extends StatelessWidget{const HomeTab({super.key,required this.api});final ApiService api;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('AYANSHA HEALTH CARE',style:TextStyle(fontWeight:FontWeight.bold))),body:ListView(padding:const EdgeInsets.all(16),children:[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(color:const Color(0xFF073C4A),borderRadius:BorderRadius.circular(24)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Welcome back 👋',style:TextStyle(color:Colors.white70)),SizedBox(height:8),Text('Your health, our priority.',style:TextStyle(color:Colors.white,fontSize:25,fontWeight:FontWeight.bold)),SizedBox(height:8),Text('Doctors, appointments and health records — all in one secure place.',style:TextStyle(color:Colors.white70))])),const SizedBox(height:22),const Text('What do you need today?',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:12),GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:2,crossAxisSpacing:12,mainAxisSpacing:12,childAspectRatio:1.35,children:[_service(c,'Find a Doctor',Icons.medical_services,DoctorsTab(api:api)),_service(c,'Book Appointment',Icons.calendar_month,BookingPage(api:api)),_service(c,'Video Consultation',Icons.videocam,ConsultationPage(api:api)),_service(c,'Lab Tests',Icons.science,LabsPage(api:api)),_service(c,'Health Records',Icons.folder_shared,RecordsTab(api:api)),_service(c,'Emergency',Icons.emergency,EmergencyPage())]),const SizedBox(height:18),Card(child:ListTile(leading:const Icon(Icons.verified_user,color:Color(0xFF0E8F8F)),title:const Text('Care you can trust'),subtitle:const Text('Your health information should only be reviewed by you and your healthcare professionals.')))]));}
