class DoctorsTab extends StatefulWidget{const DoctorsTab({super.key,required this.api});final ApiService api;@override State<DoctorsTab> createState()=>_DoctorsState();}
class _DoctorsState extends State<DoctorsTab>{late Future<List<Map<String,dynamic>>> future;@override void initState(){super.initState();future=widget.api.listDoctors();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Find a Doctor')),body:FutureBuilder<List<Map<String,dynamic>>>(future:future,builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(s.hasError)return const Center(child:Text('Unable to load doctors.'));final ds=s.data??[];return ListView(padding:const EdgeInsets.all(16),children:ds.map((d)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text('${d['name']}'),subtitle:Text('${d['specialty']}'),trailing:FilledButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>BookingPage(api:widget.api,doctorId:int.tryParse('${d['id']}'),doctorName:'${d['name']}'))),child:const Text('Book'))))).toList());}));}}

class BookingPage extends StatefulWidget{const BookingPage({super.key,required this.api,this.doctorId,this.doctorName});final ApiService api;final int? doctorId;final String? doctorName;@override State<BookingPage> createState()=>_BookingState();}
class _BookingState extends State<BookingPage>{DateTime? slot;String mode='Video';bool saving=false;final patient=TextEditingController();final phone=TextEditingController();Future<void>pick()async{final d=await showDatePicker(context:context,firstDate:DateTime.now(),lastDate:DateTime.now().add(const Duration(days:90)),initialDate:DateTime.now());if(d==null||!mounted)return;final t=await showTimePicker(context:context,initialTime:const TimeOfDay(hour:10,minute:0));if(t!=null)setState(()=>slot=DateTime(d.year,d.month,d.day,t.hour,t.minute));}Future<void>book()async{if(widget.doctorId==null||slot==null||patient.text.trim().isEmpty||phone.text.trim().isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Please complete patient, doctor and time details.')));return;}setState(()=>saving=true);try{await widget.api.createAppointment(patientName:patient.text.trim(),phone:phone.text.trim(),doctorId:widget.doctorId!,appointmentAt:slot!,mode:mode);if(mounted){await showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Appointment Confirmed ✓'),content:Text('Your $mode appointment with ${widget.doctorName??'the doctor'} is confirmed.'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Done'))]);Navigator.pop(context,true);}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));}finally{if(mounted)setState(()=>saving=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Book Appointment')),body:ListView(padding:const EdgeInsets.all(16),children:[Text(widget.doctorName??'Choose a doctor from Doctors',style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:16),TextField(controller:patient,decoration:const InputDecoration(labelText:'Patient name',prefixIcon:Icon(Icons.person),border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Mobile number',prefixIcon:Icon(Icons.phone),border:OutlineInputBorder())),const SizedBox(height:12),OutlinedButton.icon(onPressed:pick,icon:const Icon(Icons.schedule),label:Text(slot==null?'Select date & time':'${slot!.day}/${slot!.month}/${slot!.year} • ${slot!.hour.toString().padLeft(2,'0')}:${slot!.minute.toString().padLeft(2,'0')}')),const SizedBox(height:12),DropdownButtonFormField<String>(initialValue:mode,decoration:const InputDecoration(labelText:'Consultation mode',border:OutlineInputBorder()),items:const[DropdownMenuItem(value:'Video',child:Text('Video consultation')),DropdownMenuItem(value:'In-clinic',child:Text('In-clinic visit'))],onChanged:(v)=>setState(()=>mode=v!)),const SizedBox(height:22),FilledButton.icon(onPressed:saving?null:book,icon:const Icon(Icons.check_circle),label:Text(saving?'Confirming...':'Confirm Appointment'))]));@override void dispose(){patient.dispose();phone.dispose();super.dispose();}}

class BookingsTab extends StatelessWidget{const BookingsTab({super.key,required this.api});final ApiService api;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('My Bookings')),body:FutureBuilder<List<Map<String,dynamic>>>(future:api.listAppointments(),builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(s.hasError)return const Center(child:Text('Unable to load bookings.'));final a=s.data??[];return ListView(padding:const EdgeInsets.all(16),children:[if(a.isEmpty)const Card(child:ListTile(title:Text('No appointments yet'),subtitle:Text('Book a consultation to see it here.'))),...a.map((x)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.calendar_today)),title:Text('Doctor #${x['doctorId']}'),subtitle:Text('${x['appointmentAt']} • ${x['mode']}'),trailing:Text('${x['status']??'confirmed'}')))),const SizedBox(height:12),FilledButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>BookingPage(api:api))),child:const Text('Book New Appointment'))]);}));}}

